import{_ as e,o as t,c as s,a2 as o}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Data, Backup, and Operations","description":"How Hearth handles backup, restore, maintenance, diagnostics, and the global kill switch locally, and what each action does not cover.","frontmatter":{"title":"Data, Backup, and Operations","description":"How Hearth handles backup, restore, maintenance, diagnostics, and the global kill switch locally, and what each action does not cover.","outline":false},"headers":[],"relativePath":"en/design/operations.md","filePath":"en/design/operations.md","lastUpdated":1795152510000}'),n={name:"en/design/operations.md"};function r(d,a,i,l,c,p){return t(),s("div",null,[...a[0]||(a[0]=[o('<h1 id="data-backup-and-operations" tabindex="-1">Data, Backup, and Operations <a class="header-anchor" href="#data-backup-and-operations" aria-label="Permalink to &quot;Data, Backup, and Operations&quot;">​</a></h1><p class="lead">Hearth is a single-machine control plane: tasks, authority, and data stay local, with no assumption that a remote node or second device keeps state for you. The goal of operations is not more features, but the ability to see clearly, roll back, and stop.</p><h2 id="design-goals" tabindex="-1">Design goals <a class="header-anchor" href="#design-goals" aria-label="Permalink to &quot;Design goals&quot;">​</a></h2><p>Users should know where data lives, which actions modify it, and which actions only stop external effects. Backup, restore, maintenance, and diagnostics are four separate entries; stopping must not be disguised as deleting, and a database backup must not be described as a full migration.</p><p>Long-running operation is about resources, not merely &quot;it did not crash&quot;. Memory, disk, caches, logs, background tasks, and temporary files need limits and cleanup rules. Health checks, alerts, upgrades, and rollback cover the service, database, and desktop agent.</p><h2 id="trade-offs" tabindex="-1">Trade-offs <a class="header-anchor" href="#trade-offs" aria-label="Permalink to &quot;Trade-offs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>What it does</th><th>What it does not do</th></tr></thead><tbody><tr><td>Encrypted backup</td><td>Derives a key from a passphrase and packs SQLite plus necessary metadata</td><td>Does not include artifact bodies, workspaces, source bodies, or external attachments</td></tr><tr><td>Restore</td><td>Runs schema, integrity, and projection checks in a temporary database; rolls back on failure</td><td>Does not undo external effects already released</td></tr><tr><td>Maintenance</td><td>Clears expired approvals, leases, desktop commands, screenshots, pairings, and temporary files</td><td>Does not delete tasks, memory, or artifacts</td></tr><tr><td>Diagnostics</td><td>Exports a redacted health snapshot and counts</td><td>Does not include keys, absolute paths, or environment secrets</td></tr><tr><td>Global stop</td><td>Immediately halts the scheduler, pending approvals, and desktop sessions</td><td>Does not delete data; executors still need a manual start afterward</td></tr></tbody></table><p>Keep backup archives and passphrases apart. A forgotten passphrase makes the archive unrecoverable. Restore warns that current data will be replaced and asks for confirmation. Executors stay stopped after restore so old tasks cannot replay against the new data.</p><h2 id="entry-points" tabindex="-1">Entry points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry points&quot;">​</a></h2><p>Everything lives under <strong>Settings → Data</strong>: directory layout, SQLite settings tables, migration records, trash, encrypted backup, restore, maintenance, redacted diagnostics, and the global kill switch. Health, task counts, and disk usage are summarized there; there are no standalone operations or security pages.</p>',10)])])}const m=e(n,[["render",r]]);export{u as __pageData,m as default};
